Method.Source:
    public static void main(Args _args)
{
    RMarketSymbol symbol;
    // Инициализация биржи
    RMarketTable market = RMarketTable::find('TestBybit');
    RMarketApiKey key = RMarketApiKey::find('BybitTest-2025-07-11');
    str s;

    while select symbol
    {
        setPrefix(strFmt("%1 %2", market.MarketId, symbol.BaseCrypto));
        s = RMarketJob_Collateral::set(market, key, symbol.BaseCrypto, true);
        info(strFmt("Enable - %1", s));

        s = RMarketJob_Collateral::get(market, key, symbol.BaseCrypto);
        Info(strFmt("Check if enabled - %1", s));
    }
}

public static str set(RMarketTable _market, RMarketApiKey _apiKey, RMarketCryptoCode _currency, boolean _enable)
{
    RMarketMethod_Bybit_SetCollateral apiMethod = new RMarketMethod_Bybit_SetCollateral();
    apiMethod.setBaseUrl(_market.ApiUrl);
    apiMethod.setApiKey(_apiKey);
    apiMethod.initParameters(_currency, _enable);
    apiMethod.execute();
    RMarketJson_Bybit_Response result = apiMethod.getResult();
    return result.parmRetMsg();
}

public static str get(RMarketTable _market, RMarketApiKey _apiKey, RMarketCryptoCode _currency)
{
    RMarketMethod_Bybit_GetCollateral apiMethod = new RMarketMethod_Bybit_GetCollateral();
    apiMethod.setBaseUrl(_market.ApiUrl);
    apiMethod.setApiKey(_apiKey);
    apiMethod.initParameters(_currency);
    apiMethod.execute();
    RMarketJson_Bybit_GetCollateral_Item item = apiMethod.getResult();
    return item.parmCollateralSwitch() ? "ON" : "off";
}
